dtsPropsFor.BottomSheet:
/** 제목 요소의 id. aria-labelledby로 연결된다. */
titleId: string;
/** 딤 영역 클릭과 Esc 키 모두 이 핸들러를 부른다. */
onClose: () => void;
children: React.ReactNode;
/** 본문이 길어져도 항상 하단에 남는 고정 액션 영역. */
footer?: React.ReactNode;

dtsPropsFor.Chip:
label: React.ReactNode;
/** true면 ink 배경 + 700, false면 sunken 배경 + 500. */
selected?: boolean;
/** 없으면 button이 아니라 span으로 렌더된다(가짜 클릭 어포던스 방지). */
onClick?: () => void;

dtsPropsFor.ListRow:
title: string;
/** 제목 아래 한 줄. 마감이나 상태를 상대 표현으로 쓴다. */
meta: string;
/** true면 제목이 muted + 취소선이 되고 화살표가 사라진다. */
done: boolean;
/** done이 false일 때만 적용된다. 체크 테두리와 meta가 alert 색이 된다. */
urgent: boolean;
/** 체크 원에서만 발생한다. 행 클릭으로 전파되지 않는다. */
onToggle: () => void;
/** 행 본문 클릭. 상세를 여는 데 쓴다. */
onOpen: () => void;

dtsPropsFor.NextActionCard:
title: string;
/** 한 문장으로. 본문의 첫 문장만 쓰는 것이 관례다. */
description: string;
/** 동사로 끝낸다. 예: "지금 하기". */
ctaLabel: string;
onAction: () => void;

dtsPropsFor.ProgressBar:
value: number;
/** 0이면 NaN이 되지 않고 0%로 처리된다. */
max: number;

dtsPropsFor.Segment:
options: { value: string; label: string }[];
value: string;
onChange: (value: string) => void;
/** role="tablist"에 붙는 접근성 레이블. 필수다. */
"aria-label": string;

dtsPropsFor.TabBar:
/** 현재 선택된 탭. */
active: "home" | "tasks" | "notes" | "me";
onSelect: (id: "home" | "tasks" | "notes" | "me") => void;

dtsPropsFor.TextArea:
/** 여러 줄 입력용. TextField 규격을 잇되 높이만 늘리고 세로 리사이즈를 막는다. */
value?: string | number | readonly string[];
defaultValue?: string | number | readonly string[];
placeholder?: string;
rows?: number;
onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
className?: string;
/** 그 밖의 textarea 속성을 그대로 받는다. */
[key: string]: unknown;

dtsPropsFor.TextField:
/** type="date"를 넘기면 OS 기본 날짜 선택기가 뜬다. */
type?: string;
value?: string | number | readonly string[];
defaultValue?: string | number | readonly string[];
placeholder?: string;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
className?: string;
/** 그 밖의 input 속성을 그대로 받는다. */
[key: string]: unknown;
